#include <bits/stdc++.h>
using namespace std;
using ll = long long ;

int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<ll> a(3*n);
        for(int i = 0;i<3*n;i++){
            cin>>a[i];
            
        }
        sort(a.rbegin(),a.rend());
        
    vector<ll> pref(3*n + 1, 0);
    for(int i = 0;i<3*n;i++){
        pref[i+1] = pref[i] + a[i];
    }
     
     auto value = [&](int A, int B ) -> ll
        {
            
            int p1 =A;
        int p2 = A+2*B;
        int p3= 3*n -2*A-B;
        ll ans = 0;
        ans += 6LL * pref[p1];
        
        ans+= 4LL * (pref[p2] - pref[p1]);
        ans += 3LL*(pref[p3]-pref[p2]);
        
        return ans;
        };
        
        ll answer = 0;
        int B = n;
        for(int A = 0;A<=n;A++){
            B = min(B,n - A);
            while(B>0 && value(A,B-1)>= value(A,B)){
                B--;
                
            }
            answer = max(answer , value(A,B));
        }
        cout<<answer<<endl;
        
        
            }
return 0;
}
